patches.target:
ScaffoldScreen(
    modifier = Modifier
        .fillMaxSize()
        .backgroundScreenGradient(),
    snackbarHostState = snackbarHostState,
    topBar = {
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .backgroundAppBar(isBlurred = isBlurred)
        ) {
            HomeTopBar(onSettingsClick = onSettingsClick)

            if (state.showTopSearchBar) {
                SearchTextField(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(
                            start = ThemePadding.Medium,
                            end = ThemePadding.Medium,
                            bottom = ThemePadding.Small
                        ),
                    value = state.searchQuery,
                    onValueChange = ::onUpdateEntrySearchQuery
                )
            }
        }
    },
    bottomBar = {
        if (state.showBottomBar) {
            HomeBottomBar(
                searchQuery = state.searchQuery,
                onEntryQueryChange = ::onUpdateEntrySearchQuery,
                onNewEntryClick = onNewEntryClick
            )
        }
    },
    fab = {
        if (state.showFabButton) {
            IconFloatingActionButton(
                icon = UiIcon.Resource(id = R.drawable.ic_plus),
                onClick = onNewEntryClick
            )
        }
    }
) { paddingValues ->
    HomeContent(
        modifier = Modifier.padding(paddingValues = paddingValues),
        state = state,
        listState = lazyListState,
        onNewEntryClick = onNewEntryClick,
        onImportEntriesClick = onImportEntriesClick,
        onEditEntryClick = onEditEntryClick,
        onCopyEntryCodeClick = ::onCopyEntryCode,
        onDeleteEntryClick = onDeleteEntryClick,
        onRefreshEntries = ::onRefreshEntries,
        onEntriesSorted = ::onEntriesSorted
    )
}

ScaffoldScreen(
    modifier = Modifier
        .fillMaxSize()
        .backgroundScreenGradient(),
    topBar = {
        SmallTopBar(
            navigationIcon = UiIcon.Resource(id = R.drawable.ic_arrow_left),
            onNavigationClick = onNavigationClick
        )
    }
) { innerPaddingValues ->
    ImportsOptionsContent(
        modifier = Modifier
            .fillMaxSize()
            .padding(paddingValues = innerPaddingValues),
        state = state,
        onOptionSelected = { option ->
            onImportTypeSelected(option.type.ordinal)
        }
    )
}

Column(
    modifier = Modifier.padding(horizontal = ThemePadding.Large),
    verticalArrangement = Arrangement.spacedBy(space = ThemeSpacing.Medium)
) {
    Text(
        text = stringResource(id = R.string.imports_options_title),
        color = Theme.colorScheme.textNorm,
        style = Theme.typography.subtitle
    )

    Text(
        text = stringResource(id = R.string.imports_options_subtitle),
        color = Theme.colorScheme.textWeak,
        style = Theme.typography.bodyRegular
    )
}

    SelectorRow(
        titleText = UiText.Resource(id = R.string.settings_appearance_title_theme),
        options = settingsModel.themeOptions,
        onSelectedOptionChange = { themeType ->
            onThemeTypeChange(settingsModel, themeType)
        }
    )
},

anonymousData?.let { shareAnonymousData ->
    shareAnonymousData.isTelemetryEnabled?.let { isTelemetryEnabled ->
        add(
            {
                ToggleRow(
                    titleText = UiText.Resource(
                        id = R.string.settings_application_title_anonymous_telemetry
                    ),
                    isChecked = isTelemetryEnabled,
                    onCheckedChange = { newIsTelemetryEnabled ->
                        onShareTelemetryChange(
                            shareAnonymousData,
                            newIsTelemetryEnabled
                        )
                    }
                )
            }
        )
    }

    shareAnonymousData.isCrashReportEnabled?.let { isCrashReportEnabled ->
        add(
            {
                ToggleRow(
                    titleText = UiText.Resource(
                        id = R.string.settings_application_title_anonymous_crashes
                    ),
                    isChecked = isCrashReportEnabled,
                    onCheckedChange = { newIsCrashReportEnabled ->
                        onShareCrashReportChange(
                            shareAnonymousData,
                            newIsCrashReportEnabled
                        )
                    }
                )
            }
        )
    }
}

AnimatedVisibility(visible = bannerModel.shouldShowPassBanner) {
    SettingsPassBanner(
        onDismissClick = {
            onDismissPassBanner(settingsModel)
        },
        onActionClick = {
            onDiscoverAppClick(
                bannerModel.passBannerApp.id,
                bannerModel.passBannerApp.url,
                state.appConfig.buildFlavor.type
            )
        }
    )
}

if (discoverModel.shouldShowDiscoverSection) {
    SettingsSection(
        title = stringResource(id = R.string.settings_discover_section),
        contents = discoverModel.discoverProtonApps.map { discoverApp ->
            {
                NavigationRow(
                    titleText = discoverApp.title,
                    leadingIcon = discoverApp.icon,
                    description = discoverApp.description,
                    onClick = {
                        onDiscoverAppClick(
                            discoverApp.id,
                            discoverApp.url,
                            state.appConfig.buildFlavor.type
                        )
                    }
                )
            }
        }
    )
}

SettingsSection(
    title = stringResource(id = R.string.settings_support_section),
    contents = listOf(
        {
            NavigationRow(
                titleText = UiText.Resource(id = R.string.settings_support_title_how_to),
                onClick = { onHowToClick(howToUrl) }
            )
        },
        {
            NavigationRow(
                titleText = UiText.Resource(id = R.string.settings_support_title_feedback),
                onClick = onFeedbackClick
            )
        }
    )
)
